TEAMS = ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']
PENALTIES_COSTS = [100, 200, 300, 400, 500]

def task_func(goals, penalties, teams=TEAMS, penalties_costs=PENALTIES_COSTS):
    def get_value(data, team, idx):
        if isinstance(data, dict):
            return data.get(team, 0)
        if isinstance(data, (pd.Series, pd.Index)):
            try:
                return data.iloc[idx]
            except Exception:
                return 0
        try:
            return data[idx]
        except Exception:
            return 0

    rows = []
    for idx, team in enumerate(teams):
        goal_count = get_value(goals, team, idx)
        penalty_count = get_value(penalties, team, idx)

        penalty_multiplier = choice(penalties_costs)
        penalties_cost = penalty_count * penalty_multiplier
        performance_score = max(goal_count - penalty_count, 0)

        rows.append(
            {
                'Team': team,
                'Goals': goal_count,
                'Penalties': penalty_count,
                'Penalties Cost': penalties_cost,
                'Performance Score': performance_score,
            }
        )

    return pd.DataFrame(rows, columns=['Team', 'Goals', 'Penalties', 'Penalties Cost', 'Performance Score'])

