import csv


def task_func(process_name: str) -> int:
    target = os.path.basename(process_name).lower()
    if not target:
        return 0

    pids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/fo", "csv", "/nh"],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                reader = csv.reader(result.stdout.splitlines())
                for row in reader:
                    if len(row) < 2:
                        continue
                    image_name = row[0].strip().strip('"').lower()
                    if image_name == target:
                        try:
                            pids.append(int(row[1].strip().strip('"')))
                        except ValueError:
                            pass
        else:
            result = subprocess.run(
                ["ps", "-A", "-o", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    try:
                        pid = int(parts[0])
                    except ValueError:
                        continue
                    name = os.path.basename(parts[1].strip()).lower()
                    if name == target:
                        pids.append(pid)
    except Exception:
        return 0

    if not pids:
        return 0

    current_pid = os.getpid()

    for pid in pids:
        if pid == current_pid:
            continue
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except PermissionError:
            pass
        except OSError:
            pass

    time.sleep(1)

    stopped = 0
    for pid in pids:
        if pid == current_pid:
            continue
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            stopped += 1
        except PermissionError:
            pass
        except OSError:
            stopped += 1

    return stopped

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compress all files in src_folder using gzip in a background process
    and move the compressed .gz files to dst_folder.

    Returns:
        dict: {
            'success': bool,
            'message': str,
            'failed_files': list[str]
        }
    """
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist or is not a directory: {src_folder}",
            "failed_files": []
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception as exc:
        return {
            "success": False,
            "message": f"Failed to create destination folder '{dst_folder}': {exc}",
            "failed_files": []
        }

    files = [path for path in glob(os.path.join(src_folder, "*")) if os.path.isfile(path)]

    if not files:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": []
        }

    for file_path in files:
        base_name = os.path.basename(file_path)
        temp_gz_path = os.path.join(src_folder, base_name + ".gz")
        final_gz_path = os.path.join(dst_folder, base_name + ".gz")

        try:
            # Compress using gzip as a background process, writing to a temporary .gz file
            with open(temp_gz_path, "wb") as out_f:
                proc = subprocess.Popen(
                    ["gzip", "-c", file_path],
                    stdout=out_f,
                    stderr=subprocess.PIPE
                )
                _, stderr_data = proc.communicate()

            if proc.returncode != 0:
                failed_files.append(base_name)
                if os.path.exists(temp_gz_path):
                    try:
                        os.remove(temp_gz_path)
                    except OSError:
                        pass
                continue

            # Move the compressed file to the destination folder
            if os.path.exists(final_gz_path):
                try:
                    os.remove(final_gz_path)
                except OSError as exc:
                    failed_files.append(base_name)
                    if os.path.exists(temp_gz_path):
                        try:
                            os.remove(temp_gz_path)
                        except OSError:
                            pass
                    continue

            shutil.move(temp_gz_path, final_gz_path)

        except Exception:
            failed_files.append(base_name)
            if os.path.exists(temp_gz_path):
                try:
                    os.remove(temp_gz_path)
                except OSError:
                    pass

    success = len(failed_files) == 0
    if success:
        message = f"Successfully compressed and moved {len(files)} file(s) to '{dst_folder}'."
    else:
        message = (
            f"Completed with errors: {len(failed_files)} file(s) failed to compress or move."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files
    }

