import pandas as pd

def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    num_pattern = re.compile(
        r"^\s*([-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)\s*$"
    )

    def normalize(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2.0
        if isinstance(value, str):
            match = num_pattern.match(value)
            if match:
                return float(match.group(1)) * 2.0
            return value
        if isinstance(value, list):
            return [normalize(item) if not isinstance(item, dict) else item for item in value]
        return value

    normalized = {key: normalize(value) if not isinstance(value, dict) else value
                  for key, value in data.items()}

    if not normalized:
        return pd.DataFrame()

    has_list = any(isinstance(value, list) for value in normalized.values())

    try:
        if has_list:
            return pd.DataFrame(normalized)
        return pd.DataFrame([normalized])
    except Exception:
        return pd.DataFrame()

