import os
import hashlib
import json
from pathlib import Path

def task_func(directory: str) -> str:
    base_dir = Path(directory).resolve()
    output_path = base_dir / "hashes.json"

    hashes = {}

    for root, _, files in os.walk(base_dir):
        root_path = Path(root)
        for filename in files:
            file_path = (root_path / filename).resolve()

            # Do not hash the output file itself.
            if file_path == output_path:
                continue

            if not file_path.is_file():
                continue

            hasher = hashlib.sha256()
            with file_path.open("rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)

            relative_path = file_path.relative_to(base_dir).as_posix()
            hashes[relative_path] = hasher.hexdigest()

    with output_path.open("w", encoding="utf-8") as f:
        json.dump(hashes, f, indent=2, sort_keys=True)

    return str(output_path)

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

def task_func(column, data):
    if not data:
        raise ValueError("The data list is empty.")

    df = pd.DataFrame(data)

    def resolve_column(df_obj, col_name):
        if col_name in df_obj.columns:
            return col_name
        normalized = {str(c).strip().lower(): c for c in df_obj.columns}
        key = str(col_name).strip().lower()
        if key in normalized:
            return normalized[key]
        raise KeyError(f"{col_name} is not a valid column.")

    # Resolve the requested column and the date column
    target_col = resolve_column(df, column)
    date_col = resolve_column(df, "Date")

    # Validate non-negative numeric values for fitness-related columns if present
    for expected_col in ["steps", "calories burned", "distance walked"]:
        try:
            actual_col = resolve_column(df, expected_col)
        except KeyError:
            continue

        numeric_values = pd.to_numeric(df[actual_col], errors="raise")
        if (numeric_values < 0).any():
            raise ValueError(
                f"Negative values found in column '{actual_col}'."
            )

    # Compute statistics for the requested column
    series = pd.to_numeric(df[target_col], errors="raise")
    stats = {
        "sum": series.sum(),
        "mean": series.mean(),
        "min": series.min(),
        "max": series.max(),
    }

    # Prepare and draw line chart
    plot_df = df.copy()
    try:
        plot_df[date_col] = pd.to_datetime(plot_df[date_col])
    except Exception:
        pass

    fig, ax = plt.subplots()
    ax.plot(plot_df[date_col], series, marker="o")
    ax.set_xlabel("Date")
    ax.set_ylabel(column)
    ax.set_title(f"Line Chart of ({column})")

    return stats, ax

import numpy as np
import matplotlib.pyplot as plt
import re
from collections import Counter

def task_func(mystrings, text):
    if text is None or (isinstance(text, str) and text.strip() == ""):
        raise ValueError("If the input text is empty.")

    if mystrings is None:
        items = []
    elif isinstance(mystrings, str):
        # Keep a single string as one item unless it is clearly multiline/comma-separated.
        if "\n" in mystrings or "," in mystrings:
            items = [part for part in re.split(r"[,\n]+", mystrings) if part.strip()]
        else:
            items = [mystrings]
    else:
        items = list(mystrings)

    normalized = []
    for item in items:
        if item is None:
            continue
        s = str(item).strip()
        if not s:
            continue
        s = re.sub(r"\s+", "_", s.lower())
        normalized.append(s)

    counts = Counter(normalized)

    ordered_words = []
    seen = set()
    for word in normalized:
        if word not in seen:
            seen.add(word)
            ordered_words.append(word)

    fig, ax = plt.subplots()
    if ordered_words:
        ax.bar(ordered_words, [counts[word] for word in ordered_words])
    else:
        ax.bar([], [])

    ax.set_xlabel("Words")
    ax.set_ylabel("Frequency")
    ax.tick_params(axis="x", rotation=45)
    plt.setp(ax.get_xticklabels(), ha="right")
    fig.tight_layout()

    return ax

import numpy as np
import pandas as pd
from sklearn.decomposition import PCA

def task_func(array, seed=None):
    arr = np.asarray(array)

    if arr.ndim != 2:
        raise ValueError("Input array must be 2D.")

    n_samples, n_features = arr.shape

    if n_samples == 0 or n_features == 0:
        return pd.DataFrame(columns=["PC1", "PC2"])

    rng = np.random.default_rng(seed)
    shuffled_indices = rng.permutation(n_features) if n_features > 1 else np.arange(n_features)
    arr_shuffled = arr[:, shuffled_indices]

    n_components = min(2, n_features, n_samples)

    pca = PCA(n_components=n_components)
    transformed = pca.fit_transform(arr_shuffled)

    if n_components == 1:
        return pd.DataFrame(transformed, columns=["PC1"])

    return pd.DataFrame(transformed, columns=["PC1", "PC2"])

import pandas as pd
from random import randint, seed

def task_func(dictionary, item, sample_size=None, random_seed=None):
    df = pd.DataFrame(dictionary)

    positions = []
    for row_idx, row in df.iterrows():
        for col_name, value in row.items():
            if value == item:
                positions.append((row_idx, col_name))

    # Record frequency distribution internally
    _frequency_distribution = df.eq(item).sum().to_dict()

    if sample_size is not None and positions:
        sample_size = max(0, min(sample_size, len(positions)))
        if random_seed is not None:
            seed(random_seed)
        if sample_size < len(positions):
            chosen = []
            chosen_indices = set()
            while len(chosen) < sample_size:
                idx = randint(0, len(positions) - 1)
                if idx not in chosen_indices:
                    chosen_indices.add(idx)
                    chosen.append(positions[idx])
            positions = chosen

    return positions, df

