from io import StringIO

def task_func(url, table_id):
    response = requests.get(url)
    response.raise_for_status()

    soup = BeautifulSoup(response.content, "html.parser")
    table = soup.find("table", id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    if table.find("tr") is None:
        return pd.DataFrame()

    dfs = pd.read_html(StringIO(str(table)))
    return dfs[0] if dfs else pd.DataFrame()

import numpy as np
import itertools

def task_func(data_list, file_name):
    def _to_float(value):
        if value is None:
            return np.nan
        if isinstance(value, (bool, np.bool_)):
            return np.nan
        try:
            return float(value)
        except (TypeError, ValueError):
            return np.nan

    if not data_list:
        with open(file_name, "w", encoding="utf-8") as f:
            f.write("")
        return []

    numeric_rows = [
        [_to_float(v) for v in itertools.islice(row, 1, None)]
        for row in data_list
    ]

    columns = list(itertools.zip_longest(*numeric_rows, fillvalue=np.nan))
    means = []

    for col in columns:
        arr = np.asarray(col, dtype=float)
        if arr.size == 0 or np.all(np.isnan(arr)):
            means.append(np.nan)
        else:
            means.append(float(np.nanmean(arr)))

    with open(file_name, "w", encoding="utf-8") as f:
        for idx, mean_value in enumerate(means, start=2):
            f.write(f"Position {idx}: {mean_value}\n")

    return means

import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


class RequestHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _send_json_response(self, status_code, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        content_type = self.headers.get("Content-Type")
        if content_type is None:
            self._send_json_response(
                400,
                {
                    "status": "error",
                    "message": "Content-Type header is not application/json",
                },
            )
            return

        mime_type, _ = cgi.parse_header(content_type)
        if mime_type.lower() != "application/json":
            self._send_json_response(
                400,
                {
                    "status": "error",
                    "message": "Content-Type header is not application/json",
                },
            )
            return

        length_header = self.headers.get("Content-Length", "0")
        try:
            content_length = int(length_header)
        except ValueError:
            content_length = 0

        raw_body = self.rfile.read(content_length)
        try:
            body = json.loads(raw_body.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            self._send_json_response(
                400,
                {
                    "status": "error",
                    "message": "Invalid JSON",
                },
            )
            return

        if not isinstance(body, dict) or "data" not in body:
            self._send_json_response(
                400,
                {
                    "status": "error",
                    "message": "No data key in request",
                },
            )
            return

        self._send_json_response(200, SUCCESS_RESPONSE)

    def log_message(self, format, *args):
        return


def task_func():
    return RequestHandler

