import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def _get_cpu_usage_windows():
    try:
        result = subprocess.run(
            ["wmic", "cpu", "get", "loadpercentage"],
            capture_output=True,
            text=True,
            check=False,
        )
        output = result.stdout.strip()
        for line in output.splitlines():
            line = line.strip()
            if not line or line.lower() == "loadpercentage":
                continue
            try:
                return float(line)
            except ValueError:
                continue
    except Exception:
        pass
    return None


def _get_cpu_usage_unix():
    try:
        result = subprocess.run(
            "top -bn1",
            shell=True,
            capture_output=True,
            text=True,
            check=False,
        )
        output = result.stdout.strip()

        for line in output.splitlines():
            if "Cpu(s)" in line or "CPU" in line:
                parts = line.split(",")
                for part in parts:
                    part = part.strip()
                    if part.endswith("id") or " id" in part:
                        for token in part.split():
                            try:
                                idle = float(token)
                                return max(0.0, min(100.0, 100.0 - idle))
                            except ValueError:
                                continue
    except Exception:
        pass

    try:
        result = subprocess.run(
            "ps -A -o %cpu",
            shell=True,
            capture_output=True,
            text=True,
            check=False,
        )
        total = 0.0
        for line in result.stdout.splitlines():
            line = line.strip()
            if not line or "%" in line.lower():
                continue
            try:
                total += float(line)
            except ValueError:
                continue
        return max(0.0, total)
    except Exception:
        pass

    return None


def _get_cpu_usage():
    if platform.system().lower().startswith("win"):
        usage = _get_cpu_usage_windows()
    else:
        usage = _get_cpu_usage_unix()
    return 0.0 if usage is None else usage


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start_time = time.time()
    next_sample_time = start_time

    while True:
        now = time.time()
        if now - start_time >= duration:
            break

        if now < next_sample_time:
            time.sleep(next_sample_time - now)

        timestamp = time.time()
        cpu_usage = _get_cpu_usage()
        records.append({
            "timestamp": timestamp,
            "cpu_usage": cpu_usage,
        })

        next_sample_time += interval

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except OSError:
        return None

    return LOGFILE_PATH

import pandas as pd
from sklearn.preprocessing import LabelEncoder

def task_func(data):
    series = pd.Series(data)

    # Handle empty input gracefully
    if series.empty:
        return pd.DataFrame(columns=["Category", "Encoded"])

    # Drop missing values because LabelEncoder does not accept NaN
    clean_series = series.dropna()

    if clean_series.empty:
        return pd.DataFrame(columns=["Category", "Encoded"])

    encoder = LabelEncoder()
    encoder.fit(clean_series)

    return pd.DataFrame(
        {
            "Category": encoder.classes_,
            "Encoded": encoder.transform(encoder.classes_),
        }
    )

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    """
    Extract numerical data from a JSON structure using a path of keys and
    return a matplotlib Figure containing a boxplot of the extracted values.

    Parameters
    ----------
    json_data : str
        JSON-formatted string.
    key_path : list
        Sequence of keys (and optionally integer indices for lists) used to
        navigate to the target data.

    Returns
    -------
    matplotlib.figure.Figure
        Figure containing the boxplot.

    Raises
    ------
    KeyError
        If a specified key/index is not found.
    ValueError
        If the JSON string is empty/corrupted, or no numeric data is found.
    """
    if json_data is None or not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("The data string is empty or corrupted.")

    try:
        data = json.loads(json_data)
    except Exception as exc:
        raise ValueError("The data string is empty or corrupted.") from exc

    current = data
    for key in key_path or []:
        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, list) and isinstance(key, int):
            if key < 0 or key >= len(current):
                raise KeyError(key)
            current = current[key]
        else:
            raise KeyError(key)

    def _collect_numeric(obj):
        values = []

        if obj is None:
            return values

        if isinstance(obj, (bool, np.bool_)):
            return values

        if isinstance(obj, (int, float, np.integer, np.floating)):
            if np.isfinite(obj):
                values.append(float(obj))
            return values

        if isinstance(obj, str):
            s = obj.strip()
            if not s:
                raise ValueError("The data string is empty or corrupted.")
            try:
                parsed = json.loads(s)
            except Exception:
                try:
                    num = float(s)
                    if np.isfinite(num):
                        values.append(num)
                    return values
                except Exception as exc:
                    raise ValueError("The data string is empty or corrupted.") from exc
            return _collect_numeric(parsed)

        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(_collect_numeric(v))
            return values

        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                values.extend(_collect_numeric(item))
            return values

        return values

    numeric_values = _collect_numeric(current)

    if not numeric_values:
        raise ValueError("No numeric data found.")

    df = pd.DataFrame({"values": numeric_values})

    fig, ax = plt.subplots(figsize=(6, 4))
    sns.boxplot(y=df["values"], ax=ax, color="skyblue")
    ax.set_title("Boxplot of Extracted Numerical Data")
    ax.set_ylabel("Values")
    ax.set_xlabel("")
    plt.tight_layout()

    return fig
